# -*- coding: utf-8 -*-
"""本机语音转写工坊 —— 本地修复补丁（sitecustomize 自动加载）

【问题】
主程序 main.js 在启动 transcribe.py 时，只注入了 TRANSCRIBE_STUDIO_CLOUD_AI_API_KEY，
从未注入 TRANSCRIBE_STUDIO_FFMPEG / TRANSCRIBE_STUDIO_FFPROBE。
而 transcribe.py 的 find_ffmpeg() / find_ffprobe() 查找顺序是：
    1) 环境变量 TRANSCRIBE_STUDIO_FFMPEG / FFPROBE
    2) /opt/homebrew/bin、/usr/local/bin（macOS 路径）
    3) 系统 PATH 里的 ffmpeg / ffprobe
    4) site-packages 里的 imageio-ffmpeg（本机未安装）
全部落空后直接抛 RuntimeError，转写无法开始。

程序其实自带了 resources/ffmpeg/ffmpeg.exe 与 ffprobe.exe，但那段代码没用上。

【本补丁的修法】
python311._pth 中启用了 `import site`，因此 Python 启动时会自动导入
sitecustomize。这里把随包分发的 ffmpeg / ffprobe 绝对路径写进环境变量，
transcribe.py 第 1 步就能命中，转写恢复正常。

使用 setdefault：若外部已显式设置同名变量，则不覆盖，避免影响其他用法。

删除本文件即可完全回退，不修改任何原有文件。
"""

import os
from pathlib import Path

try:
    _here = Path(__file__).resolve()              # ...\resources\python-embed\site-packages\sitecustomize.py
    _embed = _here.parent.parent                  # ...\resources\python-embed
    _ffmpeg_dir = _embed.parent / "ffmpeg"        # ...\resources\ffmpeg

    for _env_name, _exe_name in (
        ("TRANSCRIBE_STUDIO_FFMPEG", "ffmpeg.exe"),
        ("TRANSCRIBE_STUDIO_FFPROBE", "ffprobe.exe"),
    ):
        _candidate = _ffmpeg_dir / _exe_name
        if _candidate.exists():
            os.environ.setdefault(_env_name, str(_candidate))
except Exception:
    # 补丁本身绝不能让 Python 启动失败
    pass
